namespace Greyhaven.Content;
public sealed class QuestObjective {public string Id {get;set;}="";public string Kind {get;set;}="";public string Target {get;set;}="";public string Text {get;set;}="";public int Amount {get;set;}=1;}
public sealed class QuestDefinition {public string Id {get;set;}="";public string Name {get;set;}="";public string Giver {get;set;}="";public string Recipient {get;set;}="";public string Description {get;set;}="";public string Completion {get;set;}="";public bool Main {get;set;}public int Fame {get;set;}public int Karma {get;set;}public List<QuestObjective> Objectives {get;set;}=[];public List<MapLoot> Rewards {get;set;}=[];}
public sealed class RoutineDefinition {public string NpcId {get;set;}="";public int WorkX {get;set;}public int WorkY {get;set;}public int HomeX {get;set;}public int HomeY {get;set;}public int SocialX {get;set;}public int SocialY {get;set;}}
public sealed class TrainerDefinition {public string NpcId {get;set;}="";public string Skill {get;set;}="";public int Value {get;set;}=1000;}
public sealed class AdventureCatalog {public List<QuestDefinition> Quests {get;set;}=[];public List<RoutineDefinition> Routines {get;set;}=[];public List<TrainerDefinition> Trainers {get;set;}=[];}
public sealed class QuestProgress {public string Id {get;set;}="";public string Status {get;set;}="available";public List<int> Counts {get;set;}=[];public double AcceptedAt {get;set;}public double CompletedAt {get;set;}}
public sealed class SkillProgress {public string Id {get;set;}="";public int Value {get;set;}public string Lock {get;set;}="up";public int Uses {get;set;}}
public sealed class NpcProgress {public string Id {get;set;}="";public int X {get;set;}public int Y {get;set;}public int Facing {get;set;}=5;public string Activity {get;set;}="working";public double MoveAt {get;set;}public double HoldUntil {get;set;}}
public sealed class AdventureProgress {public int Version {get;set;}public bool Enabled {get;set;}public List<QuestProgress> Quests {get;set;}=[];public List<SkillProgress> Skills {get;set;}=[];public List<NpcProgress> Npcs {get;set;}=[];public List<string> Talked {get;set;}=[];public uint RandomState {get;set;}=0xD1CEB00C;public int Strength {get;set;}=40;public int Dexterity {get;set;}=40;public int Intelligence {get;set;}=40;public string StrengthLock {get;set;}="up";public string DexterityLock {get;set;}="up";public string IntelligenceLock {get;set;}="up";public int Fame {get;set;}public int Karma {get;set;}public bool BeaconRestored {get;set;}public bool HeartCreated {get;set;}public bool Meditating {get;set;}public double NextSkillAt {get;set;}public double NextStatAt {get;set;}public double NextRestockAt {get;set;}public double BandageAt {get;set;}public double NextNpcAt {get;set;}public int BandageSlips {get;set;}public int BandageX {get;set;}public int BandageY {get;set;}}
public sealed record SkillDefinition(string Id,string Name,int UoId,int Start,string Stat);
public static class AdventureRules {
 public const string MainQuest="quest.beacon",Heart="quest.item.lantern-heart",Mail="quest.item.harbour-letter";public const int TotalSkillCap=7000,SkillCap=1000,StatCap=225,IndividualStatCap=125;
 public static readonly SkillDefinition[] Skills=[new("swords","Swordsmanship",40,300,"str"),new("wrestling","Wrestling",43,150,"str"),new("tactics","Tactics",27,300,"str"),new("anatomy","Anatomy",1,100,"str"),new("magery","Magery",25,300,"int"),new("evalint","Evaluating Intelligence",16,200,"int"),new("meditation","Meditation",46,200,"int"),new("healing","Healing",17,200,"dex"),new("parry","Parrying",5,150,"dex"),new("throwing","Throwing",57,250,"dex"),new("resist","Resisting Spells",26,200,"int")];
 public static SkillProgress Skill(SessionState s,string id)=>s.Adventure.Skills.FirstOrDefault(k=>k.Id==id)??throw new ContentException("Unknown skill.");
 public static double Value(SessionState s,string id)=>s.Adventure.Enabled?Skill(s,id).Value/10.0:30;
 public static NpcProgress? Npc(SessionState s,string id)=>s.Adventure.Npcs.FirstOrDefault(n=>n.Id==id);
 public static (int x,int y) Position(SessionState s,MapObject o){var n=Npc(s,o.Id);return n==null?(o.X,o.Y):(n.X,n.Y);}
 public static int Minute(SessionState s)=>(480+(int)(s.ElapsedSeconds/5)%1440)%1440;
 public static string Clock(SessionState s)=>$"{Minute(s)/60:00}:{Minute(s)%60:00}";
 public static bool Applicable(ContentPackage p,QuestDefinition d)=>p.Map.Objects.Any(o=>o.Id==d.Giver&&o.Kind=="npc")&&p.Map.Objects.Any(o=>o.Id==d.Recipient&&o.Kind=="npc")&&d.Objectives.All(o=>o.Kind switch {"obtain" or "deliver"=>true,"collect"=>p.Map.Objects.Any(m=>WorldAuthoring.ItemId(m)==o.Target),_=>p.Map.Objects.Any(m=>m.Id==o.Target)});

 public static bool IsQuestItem(WorldItem i)=>i.QuestId!="";
 public static string Title(SessionState s)=>s.Adventure.BeaconRestored?"Lantern Warden":s.Adventure.Fame>=500?"Known Wayfarer":"Wayfarer";
 public static void ValidateCatalog(ContentPackage p){var c=p.AdventureCatalog;if(c.Quests is null||c.Routines is null||c.Trainers is null||c.Quests.Count>32||c.Routines.Count>64||c.Trainers.Count>64)throw new ContentException("Invalid adventure catalog.");var ids=new HashSet<string>();foreach(var q in c.Quests){if(q==null||!ids.Add(q.Id)||string.IsNullOrWhiteSpace(q.Name)||q.Name.Length>80||q.Description is null||q.Description.Length>1000||q.Completion is null||q.Completion.Length>240||q.Objectives is null||q.Objectives.Count is <1 or >12||q.Rewards is null||q.Rewards.Count>10||q.Fame<0||q.Fame>10000||Math.Abs((long)q.Karma)>10000)throw new ContentException("Invalid quest definition.");var objectives=new HashSet<string>();foreach(var o in q.Objectives)if(o==null||!objectives.Add(o.Id)||o.Kind is not ("talk" or "visit" or "collect" or "object" or "kill" or "obtain" or "deliver" or "restore")||o.Target is null||o.Text is null||o.Text.Length>180||o.Amount is <1 or >9999)throw new ContentException("Invalid quest objective.");foreach(var reward in q.Rewards)if(reward==null||!p.Definitions.Items.Any(i=>i.Id==reward.Definition&&(!i.Stackable?reward.Amount==1:reward.Amount is >=1 and <=9999)))throw new ContentException("Invalid quest reward.");}foreach(var t in c.Trainers)if(t==null||!Skills.Any(k=>k.Id==t.Skill)||t.Value is <600 or >1200)throw new ContentException("Invalid trainer.");}
 public static void Validate(ContentPackage p,SessionState s){var a=s.Adventure;if(a==null||a.Version is <0 or >1||a.Quests is null||a.Skills is null||a.Npcs is null||a.Talked is null||a.Quests.Count>32||a.Skills.Count>Skills.Length||a.Npcs.Count>512||a.Talked.Count>512||a.Fame is <0 or >32000||a.Karma is < -32000 or >32000||a.Strength is <10 or >125||a.Dexterity is <10 or >125||a.Intelligence is <10 or >125||a.Strength+a.Dexterity+a.Intelligence>StatCap||a.RandomState==0)throw new ContentException("Invalid adventure state.");if(a.BandageSlips is <0 or >50||a.BandageAt>0&&!p.Map.Contains(a.BandageX,a.BandageY))throw new ContentException("Invalid bandage state.");bool Lock(string k)=>k is "up" or "down" or "locked";if(!Lock(a.StrengthLock)||!Lock(a.DexterityLock)||!Lock(a.IntelligenceLock))throw new ContentException("Invalid stat lock.");foreach(double t in new[]{a.NextSkillAt,a.NextStatAt,a.NextRestockAt,a.BandageAt,a.NextNpcAt})if(!double.IsFinite(t)||t<0||t>s.ElapsedSeconds+7200)throw new ContentException("Invalid adventure timer.");if(a.Skills.Any(k=>k==null||!Skills.Any(d=>d.Id==k.Id)||k.Value is <0 or >1000||!Lock(k.Lock)||k.Uses<0)||a.Skills.Select(k=>k.Id).Distinct().Count()!=a.Skills.Count||a.Skills.Sum(k=>k.Value)>TotalSkillCap||a.Enabled&&a.Skills.Count!=Skills.Length)throw new ContentException("Invalid saved skills.");if(a.Quests.Select(q=>q.Id).Distinct().Count()!=a.Quests.Count)throw new ContentException("Duplicate saved quest.");foreach(var q in a.Quests){var d=p.AdventureCatalog.Quests.FirstOrDefault(d=>d.Id==q.Id)??throw new ContentException("Unknown saved quest.");if(!Applicable(p,d)||q.Status is not ("available" or "active" or "ready" or "claimed")||q.Counts is null||q.Counts.Count!=d.Objectives.Count||q.Counts.Where((n,i)=>n<0||n>d.Objectives[i].Amount).Any()||!double.IsFinite(q.AcceptedAt)||!double.IsFinite(q.CompletedAt)||q.AcceptedAt<0||q.AcceptedAt>s.ElapsedSeconds||q.CompletedAt<0||q.CompletedAt>s.ElapsedSeconds)throw new ContentException("Invalid saved quest progress.");}
 if(a.Npcs.Any(n=>n==null||!p.Map.Objects.Any(o=>o.Id==n.Id&&o.Kind=="npc")||!p.CanStand(p.Map,n.X,n.Y)||n.Facing is <0 or >7||n.Activity is not ("working" or "socializing" or "resting" or "walking")||!double.IsFinite(n.MoveAt)||!double.IsFinite(n.HoldUntil)||n.MoveAt<0||n.HoldUntil<0||n.MoveAt>s.ElapsedSeconds+7200||n.HoldUntil>s.ElapsedSeconds+7200)||a.Npcs.Select(n=>n.Id).Distinct().Count()!=a.Npcs.Count)throw new ContentException("Invalid NPC routine state.");if(a.Talked.Distinct().Count()!=a.Talked.Count||a.Talked.Any(id=>!p.Map.Objects.Any(o=>o.Id==id&&o.Kind=="npc")))throw new ContentException("Invalid conversation record.");foreach(var item in s.Items)if(item.QuestId is null||item.Label is null||item.Label.Length>80||item.QuestId!=""&&!p.AdventureCatalog.Quests.Any(q=>q.Id==item.QuestId))throw new ContentException("Invalid quest item metadata.");}
}
